              "code": "static void Main(string[] args)\n{\n    int number;\n    int currentCount = 0;\n    int maxCount = 0;\n    Console.WriteLine(\"Enter numbers one by one (-1 to stop):\");\n    number = int.Parse(Console.ReadLine());\n    while (number != -1)\n    {\n        if (number % 2 == 0) // عدد زوجي\n        {\n            currentCount++;\n            if (currentCount > maxCount)\n                maxCount = currentCount;\n        }\n        else\n        {\n            currentCount = 0; // السلسلة انقطعت\n        }\n        number = int.Parse(Console.ReadLine());\n    }\n    Console.WriteLine(\"The longest consecutive even-number sequence length is: \" + maxCount);\n}"
